/** Generated by scaffold-crud-pages. Query hooks for ExamAnswers.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchExamAnswersList,
  fetchExamAnswersById,
  createExamAnswers,
  updateExamAnswers,
  deleteExamAnswers,
  type FetchExamAnswersListParams,
} from '~/services/httpServices/examAnswersService';
import type { CreateExamAnswersRequest, UpdateExamAnswersRequest } from '~/types/exam-answers';

const DOMAIN = 'examAnswers';

export function useExamAnswersList(params?: FetchExamAnswersListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchExamAnswersList(params),
  });
}

export function useExamAnswers(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchExamAnswersById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateExamAnswers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateExamAnswersRequest) => createExamAnswers(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateExamAnswers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateExamAnswersRequest }) =>
      updateExamAnswers(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteExamAnswers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteExamAnswers(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
